style.css:
/* This targets the body of the webpage */
body {
    font-family: Arial, sans-serif; /* Sets the font */
    background-color: #f0f0f0; /* Sets the background color */
    color: #333; /* Sets the text color */
}

/* This targets all paragraphs on the webpage */
p {
    font-size: 16px; /* Sets the font size */
    line-height: 1.5; /* Sets the line spacing */
}

/* This targets links and changes their color */
a {
    color: #0077cc; /* Sets the link color */
    text-decoration: none; /* Removes the underline from links */
}

/* This targets headers and changes their style */
h1 {
    color: #222; /* Sets the color of headers */
    text-align: center; /* Centers the text */
}
